#!/usr/bin/env python3
"""Regenerates Tests/FakeCore.swift from FltsCoreProtocol in the bindings.

Each method runs a handler a test set, else forwards to `inner` (a real core,
for counting calls), else throws. Run after the core's API changes.
"""

import pathlib
import re

root = pathlib.Path(__file__).resolve().parent.parent
gen = (root / "Generated/flts_ffi.swift").read_text()
start = gen.index("public protocol FltsCoreProtocol")
body = gen[start : gen.index("\n}", start)]

out = [
    "// Generated by scripts/gen-fake-core.py; do not edit.",
    "import Foundation",
    "@testable import FLTS",
    "",
    "/// Each method runs its handler if a test set one, else forwards to `inner`",
    "/// (a real core, for counting calls), else throws.",
    "final class FakeCore: FltsCoreProtocol, @unchecked Sendable {",
    "    let inner: (any FltsCoreProtocol)?",
    "    init(inner: (any FltsCoreProtocol)? = nil) { self.inner = inner }",
    "    private let lock = NSLock()",
    "    private var _calls: [String] = []",
    "    var calls: [String] { lock.withLock { _calls } }",
    "    func count(_ name: String) -> Int { calls.filter { $0 == name }.count }",
    "    private func record(_ name: String) { lock.withLock { _calls.append(name) } }",
    "",
]
for sig in re.findall(r"\n    (func [^\n]+)", body):
    sig = sig.strip()
    name, params, is_async, throws, ret = re.match(
        r"func (\w+)\((.*?)\)\s*(async)?\s*(throws)?\s*(?:->\s*(.+))?$", sig
    ).groups()
    ret = (ret or "").strip()
    parts = [p for p in params.split(",") if p.strip()]
    labels = [p.split(":")[0].strip() for p in parts]
    types = [p.split(":", 1)[1].strip() for p in parts]
    aw = "await " if is_async else ""
    fwd = ", ".join(f"{l}: {l}" for l in labels)
    out.append(
        f"    var {name}Handler: (({', '.join(types)}) {'async ' if is_async else ''}throws -> {ret or 'Void'})?"
    )
    if name == "shutdown":
        impl = '        record("shutdown")\n        await inner?.shutdown()'
    elif throws:
        impl = (
            f'        record("{name}")\n'
            f"        guard let h = {name}Handler else {{\n"
            f"            if let inner {{ return try {aw}inner.{name}({fwd}) }}\n"
            f'            throw CoreError.Failed(message: "not faked: {name}")\n'
            f"        }}\n"
            f"        return try {aw}h({', '.join(labels)})"
        )
    else:
        impl = (
            f'        record("{name}")\n'
            f"        if let h = {name}Handler {{ return (try? h({', '.join(labels)})) ?? nil }}\n"
            f"        return inner?.{name}({fwd})"
        )
    out.append(f"    {sig} {{\n{impl}\n    }}\n")
out.append("}")
(root / "Tests/FakeCore.swift").write_text("\n".join(out) + "\n")
